window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"M7zNTKIFlyw","speaker":"João Manuel Gonçalves Lourenço","role":"President","country":"Angola","region":"Africa","url":"https://www.youtube.com/watch?v=M7zNTKIFlyw","date":"20260922","title":"🇦🇴 Angola -  President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1414,"words":2416,"counts":{"claims":34,"promises":1,"attacks":2},"topics":[{"topic":"UN reform","share":0.292,"seconds":413},{"topic":"Cuba","share":0.1135,"seconds":160},{"topic":"African peace","share":0.1076,"seconds":152},{"topic":"Terrorism","share":0.1053,"seconds":149},{"topic":"Climate financing","share":0.0637,"seconds":90},{"topic":"Angola independence","share":0.0557,"seconds":79},{"topic":"African debt","share":0.0555,"seconds":78},{"topic":"Angola reconciliation","share":0.0534,"seconds":76},{"topic":"Africa development","share":0.0524,"seconds":74},{"topic":"Israel-Palestine","share":0.0517,"seconds":73},{"topic":"Global conflicts","share":0.0493,"seconds":70}],"timeline":[[1,84,null],[84,149,"UN reform"],[151,212,"Terrorism"],[214,302,"Terrorism"],[302,364,"African peace"],[369,460,"African peace"],[462,541,"Angola independence"],[542,618,"Angola reconciliation"],[620,689,"Global conflicts"],[691,764,"Israel-Palestine"],[765,845,"Cuba"],[846,927,"Cuba"],[928,996,"UN reform"],[998,1061,"UN reform"],[1062,1136,"Africa development"],[1139,1218,"African debt"],[1219,1309,"Climate financing"],[1309,1384,"UN reform"],[1385,1447,"UN reform"],[1449,1529,"UN reform"],[1533,1538,null]],"stances":{"UN reform":"João Manuel Gonçalves Lourenço congratulates outgoing and incoming UN officials for their dedication to preserving the organization's role in addressing global issues.","Terrorism":"João Manuel Gonçalves Lourenço notes that the current UN General Assembly session coincides with the 25th anniversary of the September 11 terrorist attacks.","African peace":"João Manuel Gonçalves Lourenço states that Angola is committed to resolving conflicts through dialogue and hosting peace initiatives.","Angola independence":"João Manuel Gonçalves Lourenço describes Angola's path to independence and peace as a historical achievement shaped by Cold War confrontations, emphasizing the lessons learned for current foreign policy.","Angola reconciliation":"João Manuel Gonçalves Lourenço states that peace and national reconciliation in Angola are now a reality, marked by award ceremonies and an upcoming monument for victims of past conflicts.","Global conflicts":"João Manuel Gonçalves Lourenço attributes regional instability to a specific stance and condemns the lack of progress in peace agreements for ongoing wars.","Israel-Palestine":"João Manuel Gonçalves Lourenço calls for the strongest international outrage and condemnation regarding the expulsion of Palestinians due to Jewish settlement expansion in the West Bank.","Cuba":"João Manuel Gonçalves Lourenço expresses concern over the unjust and insensitive manner in which Cuba has been subjected to a worsening embargo for decades.","Africa development":"João Manuel Gonçalves Lourenço argues that affordable financing, debt relief, and technology transfer are essential for Africa to achieve concrete results in implementing the 2030 agenda.","African debt":"João Manuel Gonçalves Lourenço argues that high debt servicing costs in African countries limit investment and exacerbate inequalities, necessitating immediate reform of the international financial architecture.","Climate financing":"João Manuel Gonçalves Lourenço argues for establishing affordable and additional climate financing that does not increase the debt of developing countries."},"claims":[{"t":102,"quote":"Miss Analena Baruk who preceded him in the discharge of these noble duties who did not spare efforts in her term that she carried out with undeniable competence","topic":"UN reform","kind":"fact"},{"t":129,"quote":"his excellency secretary general Antonio Gutierrez who has been working and devoted himself with persistent dedication to the great global causes building bridges for dialogue","topic":"UN reform","kind":"fact"},{"t":187,"quote":"This year's session, however, takes 25 years after the terrorist attack that destroyed the Twin Towers in New York and struck other targets on the American territory, causing thousands of civilian deaths, injuries, some of whom continue to bear physical and emotional scars to this day.","topic":"Terrorism","kind":"fact"},{"t":226,"quote":"terrorism which remains active in some countries particularly in Africa","topic":"Terrorism","kind":"fact"},{"t":244,"quote":"the world has taken a course that brings it alarmingly to close close to a global conflict over the years","topic":"Terrorism","kind":"fact"},{"t":281,"quote":"I highlighted the 21st extraordinary summit of heads of state of the African Union on the strengthening of conflict prevention and resolution mechanism in Africa recently held in Lwanda","topic":"Terrorism","kind":"self_credit"},{"t":310,"quote":"holding in July of this year in Lwanda in partnership with the United Nations Alliance of Civilization the third edition of the initiative call for peace and to wars and respect for international law","topic":"African peace","kind":"fact"},{"t":329,"quote":"Angola will host next October the Panaffrican Forum for the culture of peace and nonviolence, the so-called Lwanda bayen","topic":"African peace","kind":"fact"},{"t":399,"quote":"We call for effective implementation of the security council resolution 2719 which must ensure a predictable, adequate and sustainable financing for African Unionled peace support operation authorized by the United Nations Security Council because investing in Africa's capacity to prevent and resolve conflicts is also an investment in international peace and","topic":"African peace","kind":"fact"},{"t":437,"quote":"this session of the general assembly is of particular significance to my country as it take place in the year in which we celebrate the 50th anniversary of the Republic of Angola's admission as full member of the United Nations organization which took place in December 1976.","topic":"African peace","kind":"number"},{"t":462,"quote":"That time it was historical achievement for the Angolan people who waited more than 12 months from the date of proclamation of their national independence for the country to be accepted as a full-fledged member of the international community.","topic":"Angola independence","kind":"fact"},{"t":500,"quote":"Our interior journey towards to the attainment of peace in 2002 was closely linked to the dispute of that period which hampered the fulfillment of the dreams of Angolans and their plans to building a prosperous nation committed to its own development.","topic":"Angola independence","kind":"fact"},{"t":542,"quote":"Peace and national reconciliation is now a reality as shown through concrete gestures including the holding of award ceremonies to honor the main political leaders of national liberation struggle and representatives of all segments of civil society within the framework of the 50th anniversary of national independence.","topic":"Angola reconciliation","kind":"fact"},{"t":572,"quote":"Still within this framework, a monument in memory of all victims of the political conflict that occurred in Angola from the proclamation of national independence until achievement of peace in April 2002 will be inaugurated in this year.","topic":"Angola reconciliation","kind":"fact"},{"t":620,"quote":"Instab instability being experienced in various region of our continent is a direct consequence of that stance as it can be seen in the conflicts currently unfolding in Europe, in the Middle East, in the Persian Gulf and in Africa while tensions is mounting in the Asia Pacific","topic":"Global conflicts","kind":"fact"},{"t":643,"quote":"From what we have observed, we do not discern encouraging signs regarding the likelihood of reaching any peace agreement in the near future, in the wars between Russia and Ukraine, in the Israeli Palestinian conflict in the Middle East and in the Persian Gulf.","topic":"Global conflicts","kind":"fact"},{"t":691,"quote":"The expulsion of Palestinians from their homes and lands through expansion of Jewish settlements in West Bank must elicit the strongest international outrage and condemnation.","topic":"Israel-Palestine","kind":"fact"},{"t":707,"quote":"Attempts to dominate entire countries and regions of the globe by force of arms are leading the world towards a The food security and energy and humanitarian situation of countries and the world in general has deteriorated considerably following the outbreak of wars against Ukraine and more recently against Iran.","topic":"Israel-Palestine","kind":"fact"},{"t":735,"quote":"The toll of these wars is disastrous judging by the consequences arising from the strangulation of free do of maritime navigation through the street of Hermes and Baba Mandep.","topic":"Israel-Palestine","kind":"fact"},{"t":832,"quote":"Cuba has been over decades as a victim of an embargo that continues and worsens the living conditions of the Cuban people.","topic":"Cuba","kind":"fact"},{"t":846,"quote":"Cuba is not a terrorist state. It neither produces nor possesses nuclear weapons, chemical or material weapons that could constitute an eminent or real threat to the national security of other countries including the neighboring countries.","topic":"Cuba","kind":"fact"},{"t":877,"quote":"Cuba contributed to the fall of South Africa's racist and segregationist apathade regime, a regime broadly and unanimously condemned by the international community, and consequently became one of the signitaries to the quadrip. appetite agreement of New York of 22 December 1988.","topic":"Cuba","kind":"fact"},{"t":954,"quote":"Those countries rendered a great service when they freed humanity from the horrors of necessism, fascism and the holocaust","topic":"UN reform","kind":"fact"},{"t":1003,"quote":"New countries have emerged which at that time were and which today are strong economies with significant advances in science and technology.","topic":"UN reform","kind":"fact"},{"t":1062,"quote":"The voice of Africans must be heard in all circumstances at all times in strategic decision making processes on issues of peace, global security, financing for development as well as climate issues and global governance of artificial","topic":"Africa development","kind":"fact"},{"t":1092,"quote":"peace and votement are inseparable which compels us to consider strategies that can help accelerate the implementation of the 2030 agenda.","topic":"Africa development","kind":"fact"},{"t":1139,"quote":"African countries spend far more resources on the exorbitant cost of debt servicing than they are able to invest in health, education, infrastructure, development programs.","topic":"African debt","kind":"fact"},{"t":1157,"quote":"This situation obviously limits productive investment, deepens inequalities and economic disparities and threatens economic and social stability.","topic":"African debt","kind":"fact"},{"t":1219,"quote":"This situation clearly illustrates the need to establish affordable and additional climate financing without further aggravating the debt of developing countries.","topic":"Climate financing","kind":"fact"},{"t":1237,"quote":"Today peoples and nations have an opportunity to make a qualitative leap in their overall living conditions through fair financing mechanism for development and tools provided by in artificial intelligence in order to improve health, agriculture, public service, scientific research and economic","topic":"Climate financing","kind":"fact"},{"t":1324,"quote":"we are drawing close to the end of the tenia of the current secretary general and the appointment of the next one.","topic":"UN reform","kind":"fact"},{"t":1385,"quote":"Only within the framework of the United Nations can we make progress in seeking peaceful solutions to the conflict ravaging the world","topic":"UN reform","kind":"fact"},{"t":1449,"quote":"No weapon is more powerful than all others are used only to destroy lives, infrastructures, dreams and life plans.","topic":"UN reform","kind":"fact"},{"t":1464,"quote":"Whereas diplomacy is the only weapon that exists to unite, repair, build, and save lives, nations, and humanity itself.","topic":"UN reform","kind":"fact"}],"promises":[{"t":341,"quote":"My country takes seriously the issues relating to peace and resolution, conflict through dialogue, respect for gnomes governing international relations and defense of international law, sparing no efforts to bringing the conflicting parties closer and build consensus in Africa","topic":"African peace","kind":"promise"}],"attacks":[{"t":599,"quote":"downgrading and violation of the rules governing international relations with the logic of force, intimidation and imposition of values stemming from unilateral vision by certain countries in defense of their exclusive interests.","topic":"Angola reconciliation","target":"Unnamed opponents"},{"t":663,"quote":"We condemned the genocide against defenseless population, the elderly, women, children, bedridden, patients, health professionals, journalists and workers of international or humanitarian or organizations who are often deprived of access to most basic human rights and to essential goods for life such as water, food, and medicines.","topic":"Global conflicts","target":"Unnamed opponents"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":null,"text":"The assembly will hear an address by His Excellency Jo Manuel Gonzalez Lorenzo, President of the Republic of Angola. I request protocol to escort his excellency and invite him to address the Your Excellency Antonio Gutirez, the UN Secretary General, Your Excellency Khal Raman, the President of the 81st General Assembly, Your Excellencies Head of States and government. Distinguished delegates, ladies and gentlemen, allow me to congratulate his excellency Khalil Rahman on his election as president of the 81st session of the United Nation General Assembly in the hope that with his vast experience and profound knowledge of our organization, he will render a valuable service to the United Nations."},{"t":84,"topic":"UN reform","text":"s which is facing complex challenges that must be overcome in order to retake key role in addressing the major issues of contemporary international relations. I also congratulate Miss Analena Baruk who preceded him in the discharge of these noble duties who did not spare efforts in her term that she carried out with undeniable competence to preserve the role of the United Nations in addressing the issues that most concerned the international community I would like also to congratulate his excellency secretary general Antonio Gutierrez who has been working and devoted himself with persistent dedication to the great global causes building bridges for dialogue in the search for peaceful solutions to the problems facing humanity today."},{"t":151,"topic":"Terrorism","text":"We highlight his exemplary contribution as a man of dialogue, an advocate of the United Nation Charter and International Law, a tireless advocate of the need to protect the planet from harmful effects of climate change and a champion of the global debate on global governance of artificial intelligence. Mr. President, your excellencies, the United Nations General Assembly is always held in the month of September. This year's session, however, takes 25 years after the terrorist attack that destroyed the Twin Towers in New York and struck other targets on the American territory, causing thousands of civilian deaths, injuries, some of whom continue to bear physical and emotional scars to this day."},{"t":214,"topic":"Terrorism","text":"I'd like to take this opportunity to once again to condemn terrorism in all its forms wherever it occurs. In addition to terrorism which remains active in some countries particularly in Africa, the situation of global peace and security has been worsening year after year [snorts] bringing us to the present moment in which we note with deep concern that the world has taken a course that brings it alarmingly to close close to a global conflict over the years, Angola has sought to make its contribution to building and consolidation of peace in Africa and the world. But the current situation in no way reflects the aspirations of peoples for harmony and understanding amongst nations. Among these contributions to peace are several initiatives undertaken in Africa of which I highlighted the 21st extraordinary summit of heads of state of the African Union on the strengthening of conflict prevention and resolution mechanism in Africa recently held in Lwanda which opened serious and sound prospect for resolving the problems affecting peace."},{"t":302,"topic":"African peace","text":"peace and stability on the African continent. Also worthy of particular attention is the holding in July of this year in Lwanda in partnership with the United Nations Alliance of Civilization the third edition of the initiative call for peace and to wars and respect for international law. In this same context, Angola will host next October the Panaffrican Forum for the culture of peace and nonviolence, the so-called Lwanda bayen. My country takes seriously the issues relating to peace and resolution, conflict through dialogue, respect for gnomes governing international relations and defense of international law, sparing no efforts to bringing the conflicting parties closer and build consensus in Africa."},{"t":369,"topic":"African peace","text":"We remain We remain available to render our attention and contribution to resolving the conflicts that persist on the continent. Our paradigm for peacebuilding initiatives is based on the search for realistic and sustainable solutions within the principle of African solutions to Afric to conflicts in Africa. We call for effective implementation of the security council resolution 2719 which must ensure a predictable, adequate and sustainable financing for African Unionled peace support operation authorized by the United Nations Security Council because investing in Africa's capacity to prevent and resolve conflicts is also an investment in international peace and Your excellencies, ladies and gentlemen, this session of the general assembly is of particular significance to my country as it take place in the year in which we celebrate the 50th anniversary of the Republic of Angola's admission as full member of the United Nations organization which took place in December 1976."},{"t":462,"topic":"Angola independence","text":"That time it was historical achievement for the Angolan people who waited more than 12 months from the date of proclamation of their national independence for the country to be accepted as a full-fledged member of the international community. &gt;&gt; That event of great significance for the history of my country took place in a global context in which Angola became a victim of confrontation between world powers in the struggle for control of sphere of influence within the spirit of cold war. Our interior journey towards to the attainment of peace in 2002 was closely linked to the dispute of that period which hampered the fulfillment of the dreams of Angolans and their plans to building a prosperous nation committed to its own development. These facts belong to the past but have left us with a wealth of experience and lessons that we have drawn upon to build peace, understanding and reconciliation among all Angolans and to chart the course of our foreign policy."},{"t":542,"topic":"Angola reconciliation","text":"Peace and national reconciliation is now a reality as shown through concrete gestures including the holding of award ceremonies to honor the main political leaders of national liberation struggle and representatives of all segments of civil society within the framework of the 50th anniversary of national independence. dependence. Still within this framework, a monument in memory of all victims of the political conflict that occurred in Angola from the proclamation of national independence until achievement of peace in April 2002 will be inaugurated in this year. Mr. President, excellencies, nowadays we are witnessing a downgrading and violation of the rules governing international relations with the logic of force, intimidation and imposition of values stemming from unilateral vision by certain countries in defense of their exclusive interests."},{"t":620,"topic":"Global conflicts","text":"Instab instability being experienced in various region of our continent is a direct consequence of that stance as it can be seen in the conflicts currently unfolding in Europe, in the Middle East, in the Persian Gulf and in Africa while tensions is mounting in the Asia Pacific From what we have observed, we do not discern encouraging signs regarding the likelihood of reaching any peace agreement in the near future, in the wars between Russia and Ukraine, in the Israeli Palestinian conflict in the Middle East and in the Persian Gulf. We condemned the genocide against defenseless population, the elderly, women, children, bedridden, patients, health professionals, journalists and workers of international or humanitarian or organizations who are often deprived of access to most basic human rights and to essential goods for life such as water, food, and medicines."},{"t":691,"topic":"Israel-Palestine","text":"The expulsion of Palestinians from their homes and lands through expansion of Jewish settlements in West Bank must elicit the strongest international outrage and condemnation. Attempts to dominate entire countries and regions of the globe by force of arms are leading the world towards a The food security and energy and humanitarian situation of countries and the world in general has deteriorated considerably following the outbreak of wars against Ukraine and more recently against Iran. The toll of these wars is disastrous judging by the consequences arising from the strangulation of free do of maritime navigation through the street of Hermes and Baba Mandep. a situation that has created serious risk of disruption to logistic supply chains in general and to food and energy supply chains in particular with devastating effects on the most vulnerable countries."},{"t":765,"topic":"Cuba","text":"Today we live in an environment of global anarchy in which the use of force prevails over the force of reason and law in blatant opposition to the gnomes governing international relations. In view of these, there's every need for profound reflection within the United Nations, the only institutions on the planet which has and which brings together all nations of the world in order to find the best solution for achieving global peace. Our appeal is for us to act with wisdom and courage to restore the central role of the United Nations in its responsibility and irrespons irreplaceable mission in maintaining global peace. Ladies and gentlemen, we are concerned by the injust manner and indicative of great human insensitivity in which Cuba has been over decades as a victim of an embargo that continues and worsens the living conditions of the Cuban people."},{"t":846,"topic":"Cuba","text":"Cuba is not a terrorist state. It neither produces nor possesses nuclear weapons, chemical or material weapons that could constitute an eminent or real threat to the national security of other countries including the neighboring countries. On the contrary, on the contrary, Cuba contributed to the fall of South Africa's racist and segregationist apathade regime, a regime broadly and unanimously condemned by the international community, and consequently became one of the signitaries to the quadrip. appetite agreement of New York of 22 December 1988. as the embargo is chiefly responsible for the clamitus situation in which Cuba and the Cuban people find themselves and since it is inhumane, unfair and violates all the principles and norms of international law, we once again call for the end to the embargo against Cuba."},{"t":928,"topic":"UN reform","text":"Ladies and gentlemen, today we witnessing to the direct invest in involvement of certain permanent members of the United Nations Security Council in in the bloodiest and most destructive conflicts in our time in Europe and the Persian Gulf, which constitutes a cause for concern and a bad example for the rest of the world. Those countries rendered a great service when they freed humanity from the horrors of necessism, fascism and the holocaust and should therefore preserve that capital and legacy as li liberators at a time when good governance of countries is widely advocated. The governance of the world likewise calls for a new more democratic and just world order. One that is not only based on the power of the restricted club of victors of a war that took place eight decades ago."},{"t":998,"topic":"UN reform","text":"Since then the world has come to know different reality. New countries have emerged which at that time were and which today are strong economies with significant advances in science and technology. It is therefore becoming increasingly pressing and urgent to undertake a profound reform of the Nation Security Council in which Africa, Latin America and Asia should adequately be represented as permanent members with all the powers inherent therein. In this context, the Republic of Angola reaffirms its full support to the common African position enshrined in the aolini consensus and the certain declaration."},{"t":1062,"topic":"Africa development","text":"The voice of Africans must be heard in all circumstances at all times in strategic decision making processes on issues of peace, global security, financing for development as well as climate issues and global governance of artificial Mr. President, your excellencies, peace and votement are inseparable which compels us to consider strategies that can help accelerate the implementation of the 2030 agenda. The important decisions adopted under the pact for the future and the severe commitment can help advance development programs in Africa. However, in order to achieve concrete results in this area, it is essential to ensure affordable financing, debt relief, technology transfer, capacity building, and a greater participation of international financial institutions."},{"t":1139,"topic":"African debt","text":"African countries spend far more resources on the exorbitant cost of debt servicing than they are able to invest in health, education, infrastructure, development programs. This situation obviously limits productive investment, deepens inequalities and economic disparities and threatens economic and social stability. In view of this, it is imperative to correct these distortions and I therefore reiterate the call for the immediate reform of the international financial architecture in order to make it fairer, more equitable, democratic and good towards the progress and well-being of humankind. These challenges are inherent in inherently complex and uh further exacerbated by climate change which has a severe impact on Africa with severe and prolonged droughts, floods, desertification, food insecurity and population displacement."},{"t":1219,"topic":"Climate financing","text":"This situation clearly illustrates the need to establish affordable and additional climate financing without further aggravating the debt of developing countries. Today peoples and nations have an opportunity to make a qualitative leap in their overall living conditions through fair financing mechanism for development and tools provided by in artificial intelligence in order to improve health, agriculture, public service, scientific research and economic In this regard, I consider that the global digital compact opens new prospects for cooperation to bridge the digital divide, expand digital public infrastructure, promote training and innovation, strengthen cyber security, and build more inclusive, secure, and human- centered governance of artificial To that end, I believe there's a need to strengthen north south and triangular cooperation in order to"},{"t":1309,"topic":"UN reform","text":"make the digital revolution in an instrument of inclusion, sovereignty and development rather than a source of dependence and inequality. we are drawing close to the end of the tenia of the current secretary general and the appointment of the next one. An act of greater importance given that the person chosen must possess the qualities of independence, integrity, competence and courage to build consensus, uphold the charter, promote conflict prevention, lead the necessary reforms, and seek solutions to address the organization's financial crisis. &gt;&gt; The Republic of Angola reaffirms its to the United Nations, convinced that only at the level of this institution will it be possible to safeguard the achievements of the recent decades in terms of respect for international law."},{"t":1385,"topic":"UN reform","text":"Only within the framework of the United Nations can we make progress in seeking peaceful solutions to the conflict ravaging the world within a framework in which macaterism serves as the mechanism for bringing together ideas, political wills and initiatives conducive to global peace. We political leaders and rulers of today will be judged in the future by our ability to replace confrontation with dialogue, predatory competition with exclusion with solidarity, and the force of arms with the force of law. Only in this way will we build a more just, peaceful and inclusive international order capable of ensuring progress and well-being of humankind, leaving no one behind."},{"t":1449,"topic":"UN reform","text":"No weapon is more powerful than all others are used only to destroy lives, infrastructures, dreams and life plans. Whereas diplomacy is the only weapon that exists to unite, repair, build, and save lives, nations, and humanity itself. For this reason, the United Nations Organization must equip itself with the appropriate tools and means to fulfill the theme of this 81st session of its general assembly, namely restoring trust, managing transformation, empowering it to become an organization that delivers for All thank you very much for your kind &gt;&gt; On behalf of this assembly, I wish thank the president of Angola."},{"t":1533,"topic":null,"text":"We have heard the last speaker in the general debate for this meeting. The"}],"compare":[{"topic":"UN & its reform","share":0.292,"mean":0.2043,"rank":48,"others":170},{"topic":"Africa","share":0.2154,"mean":0.0225,"rank":4,"others":36},{"topic":"Cuba","share":0.1135,"mean":0.0108,"rank":4,"others":23},{"topic":"Terrorism","share":0.1053,"mean":0.0024,"rank":3,"others":6},{"topic":"Climate Change","share":0.0637,"mean":0.0427,"rank":54,"others":77},{"topic":"Israel–Palestine","share":0.0517,"mean":0.0524,"rank":70,"others":76},{"topic":"International Law & Order","share":0.0493,"mean":0.0605,"rank":91,"others":102}]};
